begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000009','profiles@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000009','Embedding profiles');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000009','owner',now());
create temporary table profile_revisions(kind text primary key,result jsonb);
grant all on profile_revisions to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000009","role":"authenticated"}',true);
insert into profile_revisions values('source',public.save_case_revision('20000000-0000-4000-8000-000000000009','{"title":"Release","template":"product_delivery","outcome":"unknown","problem":"Risk","context":"Team","constraints":"No downtime","approach":"Canary","observedOutcome":"Unknown","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","conceptIds":[],"sources":[]}'));
select public.publish_case_revision((select (result->>'revisionId')::uuid from profile_revisions where kind='source'),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions,jsonb_each_text(content) where id=(select (result->>'revisionId')::uuid from profile_revisions where kind='source') and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
select throws_ok($$select public.save_case_revision('20000000-0000-4000-8000-000000000009','{}',null,'wrong',1536)$$,'22023','Embedding configuration mismatch','unsupported profile rejected');
insert into profile_revisions values('target',public.prepare_case_embedding_revision('20000000-0000-4000-8000-000000000009',(select (result->>'caseId')::uuid from profile_revisions where kind='source'),(select (result->>'revisionId')::uuid from profile_revisions where kind='source'),'text-embedding-3-small',1536));
select is((select embedding_model from public.case_revisions where id=(select (result->>'revisionId')::uuid from profile_revisions where kind='target')),'text-embedding-3-small','replacement profile is explicit');
select is((select published_revision_id from public.cases),(select (result->>'revisionId')::uuid from profile_revisions where kind='source'),'preparation preserves published source');
select is(public.prepare_case_embedding_revision('20000000-0000-4000-8000-000000000009',(select (result->>'caseId')::uuid from profile_revisions where kind='source'),(select (result->>'revisionId')::uuid from profile_revisions where kind='source'),'text-embedding-3-small',1536)->>'revisionId',(select result->>'revisionId' from profile_revisions where kind='target'),'retry reuses pending revision');
select is((select count(*) from public.search_knowledge('20000000-0000-4000-8000-000000000009','Canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',40,'text-embedding-3-small')),0::bigint,'OpenAI search excludes Gemini keyword and vector hits');
select is((select count(*) from public.search_knowledge('20000000-0000-4000-8000-000000000009','Canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',40,'gemini-embedding-2')),9::bigint,'source profile remains searchable before publication');
select public.publish_case_revision((select (result->>'revisionId')::uuid from profile_revisions where kind='target'),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions,jsonb_each_text(content) where id=(select (result->>'revisionId')::uuid from profile_revisions where kind='target') and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'text-embedding-3-small',1536);
select is((select published_revision_id from public.cases),(select (result->>'revisionId')::uuid from profile_revisions where kind='target'),'ready replacement publishes atomically');
select is((select count(*) from public.case_sections where revision_id=(select (result->>'revisionId')::uuid from profile_revisions where kind='source')),9::bigint,'historical source sections are retained');
select is((select count(*) from public.search_knowledge('20000000-0000-4000-8000-000000000009','Canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',40,'text-embedding-3-small')),9::bigint,'target profile is searchable after publication');
select is((select count(*) from public.search_knowledge('20000000-0000-4000-8000-000000000009','Canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',40,'gemini-embedding-2')),0::bigint,'old vectors are excluded from new retrieval');
select throws_ok($$select public.prepare_case_embedding_revision('20000000-0000-4000-8000-000000000009',(select (result->>'caseId')::uuid from profile_revisions where kind='source'),(select (result->>'revisionId')::uuid from profile_revisions where kind='source'),'text-embedding-3-small',1536)$$,'40001','Embedding migration source changed','stale source is rejected');
select throws_ok($$select public.prepare_case_embedding_revision('20000000-0000-4000-8000-000000000008',(select (result->>'caseId')::uuid from profile_revisions where kind='source'),(select (result->>'revisionId')::uuid from profile_revisions where kind='target'),'text-embedding-3-small',1536)$$,'42501',null,'forged workspace is rejected');
select public.save_case_revision('20000000-0000-4000-8000-000000000009',(select jsonb_set(content,'{title}','"Pending user edit"') from public.case_revisions where id=(select (result->>'revisionId')::uuid from profile_revisions where kind='target')),(select (result->>'caseId')::uuid from profile_revisions where kind='source'));
select throws_ok($$select public.prepare_case_embedding_revision('20000000-0000-4000-8000-000000000009',(select (result->>'caseId')::uuid from profile_revisions where kind='source'),(select (result->>'revisionId')::uuid from profile_revisions where kind='target'),'gemini-embedding-2',1536)$$,'55000','Pending case edit blocks embedding migration','unrelated pending content is preserved');
insert into profile_revisions values('unpublished',public.save_case_revision('20000000-0000-4000-8000-000000000009',(select content from public.case_revisions where id=(select (result->>'revisionId')::uuid from profile_revisions where kind='source'))));
select public.fail_case_index((select (result->>'revisionId')::uuid from profile_revisions where kind='unpublished'));
select is(public.prepare_case_embedding_revision('20000000-0000-4000-8000-000000000009',(select (result->>'caseId')::uuid from profile_revisions where kind='unpublished'),(select (result->>'revisionId')::uuid from profile_revisions where kind='unpublished'),'text-embedding-3-small',1536)->>'indexState','pending','unpublished failed source can migrate');
select * from finish();
rollback;
